#!/usr/bin/env python3
# SPDX-License-Identifier: LGPL-2.1-or-later
"""Writes src/papermetrics_tables.c: the advance widths, in thousandths
of an em, of the twelve standard PostScript text faces -- Times,
Helvetica and Courier, each roman, bold, italic and bold italic -- for
the Latin-1 range and Windows-1252's extras, with each face's ascent and
descent (the line gap shared between them, so a line is 1.2 em).

The numbers are read from the URW base 35 fonts (gsfonts), which are
metric clones of Adobe's: their widths are Adobe's Core 14 AFM widths,
which Adobe licenses to be "used, copied, and distributed for any
purpose and without charge". Only numbers are taken; no outline is.

    python3 tools/gen_papermetrics.py [/usr/share/fonts/gsfonts]
"""
import sys
from fontTools.ttLib import TTFont

DIR = sys.argv[1] if len(sys.argv) > 1 else '/usr/share/fonts/gsfonts'
FACES = [  # index = class * 4 + bold * 2 + italic... in this order
    ('Times-Roman', 'NimbusRoman-Regular'), ('Times-Italic', 'NimbusRoman-Italic'),
    ('Times-Bold', 'NimbusRoman-Bold'), ('Times-BoldItalic', 'NimbusRoman-BoldItalic'),
    ('Helvetica', 'NimbusSans-Regular'), ('Helvetica-Oblique', 'NimbusSans-Italic'),
    ('Helvetica-Bold', 'NimbusSans-Bold'), ('Helvetica-BoldOblique', 'NimbusSans-BoldItalic'),
    ('Courier', 'NimbusMonoPS-Regular'), ('Courier-Oblique', 'NimbusMonoPS-Italic'),
    ('Courier-Bold', 'NimbusMonoPS-Bold'), ('Courier-BoldOblique', 'NimbusMonoPS-BoldItalic'),
]
# Windows-1252's 0x80-0x9F, the slots the table keeps for them.
CP1252 = [0x20AC, 0, 0x201A, 0x0192, 0x201E, 0x2026, 0x2020, 0x2021, 0x02C6, 0x2030, 0x0160, 0x2039,
          0x0152, 0, 0x017D, 0, 0, 0x2018, 0x2019, 0x201C, 0x201D, 0x2022, 0x2013, 0x2014,
          0x02DC, 0x2122, 0x0161, 0x203A, 0x0153, 0, 0x017E, 0x0178]

def codepoint(slot):
    c = 0x20 + slot
    if 0x80 <= c <= 0x9F:
        return CP1252[c - 0x80]
    return 0 if c == 0x7F else c

out = ['/* SPDX-License-Identifier: LGPL-2.1-or-later */',
       '/* Generated by tools/gen_papermetrics.py -- do not edit. Advance widths',
       '   in 1/1000 em of the standard PostScript text faces (Adobe Core 14',
       '   metrics, read from their URW metric clones), slot = codepoint - 0x20,',
       '   0x80-0x9F holding Windows-1252\'s characters; 0 where the face has none. */',
       '#include "papermetrics.h"', '']
asc = []
for name, fn in FACES:
    t = TTFont('%s/%s.otf' % (DIR, fn))
    upm = t['head'].unitsPerEm
    cmap = t.getBestCmap(); hm = t['hmtx']; hh = t['hhea']
    ws = []
    for s in range(224):
        cp = codepoint(s)
        g = cmap.get(cp) if cp else None
        ws.append(round(hm[g][0] * 1000 / upm) if g else 0)
    gap = hh.lineGap * 1000 // upm
    if len(asc) % 4 == 0:   # the family's roman: one line height for all four styles
        fam = (hh.ascent * 1000 // upm + gap // 2, -hh.descent * 1000 // upm + gap - gap // 2)
    asc.append((fam[0], fam[1], name))
    out.append('/* %s */' % name)
    out.append('static const u16 w_%s[224] = {' % name.replace('-', '_'))
    for i in range(0, 224, 14):
        out.append('    ' + ', '.join('%d' % w for w in ws[i:i + 14]) + ',')
    out.append('};')
out.append('')
out.append('const plat_paper_table g_plat_paper_faces[PLAT_PAPER_FACES] = {')
for (a, d, name) in asc:
    out.append('    { w_%s, %d, %d },' % (name.replace('-', '_'), a, d))
out.append('};')
open('src/papermetrics_tables.c', 'w').write('\n'.join(out) + '\n')
print('wrote src/papermetrics_tables.c')
